import React from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { cycleChordFingering } from '../../../store/chordsSlice';
import { generateChord } from '../utils/chordGenerator';

// Note: Static chord data has been moved to __tests__ for validation only
// The generator is now the primary source of chord data

interface ChordChartProps {
  chord: string;
  instrument: string;
  small?: boolean;
}

const ChordChart: React.FC<ChordChartProps> = ({ chord, instrument, small = false }) => {
  const dispatch = useDispatch();
  const chordFingerings = useSelector((state: any) => state.chords.chordFingerings);
  
  // Calculate new sizes with exact same aspect ratio as original
  // Original sizes were: small: width 120, height 150 (ratio 0.8)
  //                      regular: width 200, height 250 (ratio 0.8)
  // Now we'll reduce by 60% while maintaining ratio
  const size = small ? { width: 48, height: 60 } : { width: 80, height: 120 };
  
  // Get the current fingering index for this chord (default to 0)
  const currentFingeringIndex = chordFingerings[chord] || 0;
  
  // Handle right-click to cycle through fingering alternatives
  const handleRightClick = (e: any) => {
    e.preventDefault(); // Prevent context menu
    dispatch(cycleChordFingering(chord));
  };
  
  const renderFretboardChord = (instrument: string) => {
    // Use generator as primary source (no static data fallback)
    let chordData: any = generateChord(chord, instrument);
    
    if (!chordData) {
      return (
        <div className="chord-not-found">
          <p style={{ fontSize: small ? '10px' : '12px', color: '#999' }}>
            Chord "{chord}" not yet supported for {instrument}
          </p>
        </div>
      );
    }
    
    // Handle alternative fingerings from generator
    if (chordData && chordData.inversions) {
      const alternatives = chordData.inversions || [];
      const totalFingerings = 1 + alternatives.length; // 1 for default + alternatives
      
      // Wrap around if current index exceeds available fingerings
      const validIndex = currentFingeringIndex % totalFingerings;
      
      // Use alternative fingering if index > 0
      if (validIndex > 0 && alternatives[validIndex - 1]) {
        chordData = alternatives[validIndex - 1];
      }
    }
    
    if (!chordData) {
      return <div>Chord not found: {chord}</div>;
    }
    
    let strings = 6;
    if (instrument === 'ukulele' || instrument === 'bassUkulele' || instrument === 'baritoneUkulele' || instrument === 'bassGuitar') strings = 4;
    
    // Calculate fret window for display
    const frettedNotes = chordData.frets.filter((fret: any) => fret > 0);
    const minFret = frettedNotes.length > 0 ? Math.min(...frettedNotes) : 1;
    const maxFret = frettedNotes.length > 0 ? Math.max(...frettedNotes) : 5;
    
    // Determine the display window (5 frets wide)
    let startFret;
    if (maxFret <= 5 || minFret <= 1) {
      // Show frets 1-5 (traditional view)
      startFret = 1;
    } else {
      // Show a window that includes all fretted notes
      const span = maxFret - minFret;
      if (span <= 4) {
        // All notes fit in 5-fret window, center them
        const center = Math.floor((minFret + maxFret) / 2);
        startFret = Math.max(1, center - 2);
      } else {
        // Use full span, starting from minFret
        startFret = minFret;
      }
    }
    
    const frets = 5; // Always display 5 frets
    const isNutShown = startFret === 1;
    const stringSpacing = size.width / (strings + 1);
    const fretSpacing = (size.height - 60) / frets;

    return (
      <svg width={size.width} height={size.height} className="fretboard">
        {/* Fret lines */}
        {Array.from({ length: frets + 1 }, (_, i: number) => (
          <line
            key={`fret-${i}`}
            x1={stringSpacing}
            y1={40 + i * fretSpacing}
            x2={size.width - stringSpacing}
            y2={40 + i * fretSpacing}
            stroke={i === 0 ? '#333' : '#666'}
            strokeWidth={i === 0 ? (isNutShown ? 3 : 1) : 1}
          />
        ))}

        {/* Fret number labels - show only marked frets (3, 5, 7, 9, 12, 15, etc.) */}
        {Array.from({ length: frets }, (_, i: number) => {
          const fretNumber = startFret + i;
          const isMarkedFret = fretNumber === 3 || fretNumber === 5 || fretNumber === 7 || 
                              fretNumber === 9 || fretNumber === 12 || fretNumber === 15 || 
                              fretNumber === 17 || fretNumber === 19 || fretNumber === 21 || 
                              fretNumber === 24;
          
          if (isMarkedFret) {
            return (
              <text
                key={`fret-label-${fretNumber}`}
                x={stringSpacing / 2}
                y={40 + (i + 0.5) * fretSpacing + 2}
                textAnchor="middle"
                fontSize={small ? '7' : '9'}
                fontWeight="bold"
              >
                {fretNumber}
              </text>
            );
          }
          return null;
        })}
        
        {/* String lines */}
        {Array.from({ length: strings }, (_, i: number) => (
          <line
            key={`string-${i}`}
            x1={stringSpacing * (i + 1)}
            y1={40}
            x2={stringSpacing * (i + 1)}
            y2={40 + frets * fretSpacing}
            stroke="#666"
            strokeWidth={1}
          />
        ))}

        {/* Adjust circle sizes for smaller overall dimensions */}
        {chordData.frets.map((fret: number, stringIndex: number) => {
          if (fret === -1) {
            // X mark for muted string - make smaller
            return (
              <g key={`mute-${stringIndex}`}>
                <line
                  x1={stringSpacing * (stringIndex + 1) - 4}
                  y1={25 - 4}
                  x2={stringSpacing * (stringIndex + 1) + 4}
                  y2={25 + 4}
                  stroke="#ff0000"
                  strokeWidth={1.5}
                />
                <line
                  x1={stringSpacing * (stringIndex + 1) - 4}
                  y1={25 + 4}
                  x2={stringSpacing * (stringIndex + 1) + 4}
                  y2={25 - 4}
                  stroke="#ff0000"
                  strokeWidth={1.5}
                />
              </g>
            );
          } else if (fret === 0) {
            // Open string circle - make smaller
            return (
              <circle
                key={`open-${stringIndex}`}
                cx={stringSpacing * (stringIndex + 1)}
                cy={25}
                r={small ? 2 : 3}
                fill="none"
                stroke="#333"
                strokeWidth={1.5}
              />
            );
          } else if (fret > 0) {
            // Finger position - calculate relative to the fret window
            const relativeFret = fret - startFret + 1;
            // Only show if within the current fret window
            if (relativeFret >= 1 && relativeFret <= frets) {
              return (
                <circle
                  key={`finger-${stringIndex}`}
                  cx={stringSpacing * (stringIndex + 1)}
                  cy={40 + (relativeFret - 0.5) * fretSpacing}
                  r={small ? 3 : 4}
                  fill="#333"
                />
              );
            }
          }
          return null;
        })}

        {/* Smaller font for finger numbers */}
        {chordData.fingers?.map((finger: number, stringIndex: number) => {
          const fret = chordData.frets[stringIndex];
          if (finger > 0 && fret > 0) {
            // Calculate relative fret position
            const relativeFret = fret - startFret + 1;
            // Only show if within the current fret window
            if (relativeFret >= 1 && relativeFret <= frets) {
              return (
                <text
                  key={`finger-num-${stringIndex}`}
                  x={stringSpacing * (stringIndex + 1)}
                  y={40 + (relativeFret - 0.5) * fretSpacing + 2}
                  textAnchor="middle"
                  fill="white"
                  fontSize={small ? '6' : '8'}
                  fontWeight="bold"
                >
                  {finger}
                </text>
              );
            }
          }
          return null;
        })}
        
        {/* Generated chord indicator */}
        {chordData.isGenerated && (
          <text
            x={size.width / 2}
            y={size.height - 5}
            textAnchor="middle"
            fill="#666"
            fontSize={small ? '10' : '12'}
            fontStyle="italic"
          >
            *
          </text>
        )}
      </svg>
    );
  };

  const renderPianoChord = () => {
    // Use generator as primary source (no static data fallback)
    let chordData: any = generateChord(chord, 'piano');
    
    if (!chordData) {
      return (
        <div className="chord-not-found" style={{ padding: '10px', textAlign: 'center' }}>
          <p style={{ fontSize: small ? '10px' : '12px', color: '#999' }}>
            Chord "{chord}" not yet supported for piano
          </p>
        </div>
      );
    }

    // Handle both array format (legacy) and object format (with inversions)
    let chordNotes: string[];
    
    if (Array.isArray(chordData)) {
      // Legacy format: just an array of notes
      chordNotes = chordData;
    } else if (chordData.notes) {
      // New format: object with notes and inversions
      chordNotes = chordData.notes;
      
      // Handle inversions if available
      if (chordData.inversions && chordData.inversions.length > 0) {
        const totalVersions = 1 + chordData.inversions.length; // root position + inversions
        const validIndex = currentFingeringIndex % totalVersions;
        
        // Use inversion if index > 0
        if (validIndex > 0 && chordData.inversions[validIndex - 1]) {
          chordNotes = chordData.inversions[validIndex - 1];
        }
      }
    } else {
      return (
        <div className="chord-not-found" style={{ padding: '10px', textAlign: 'center' }}>
          <p style={{ fontSize: small ? '10px' : '12px', color: '#999' }}>
            Invalid chord data format
          </p>
        </div>
      );
    }

    // Map note names to semitones for octave windowing
    const noteToSemitone: Record<string, number> = {
      'C': 0, 'B#': 0,
      'C#': 1, 'Db': 1,
      'D': 2,
      'D#': 3, 'Eb': 3,
      'E': 4, 'Fb': 4,
      'F': 5, 'E#': 5,
      'F#': 6, 'Gb': 6,
      'G': 7,
      'G#': 8, 'Ab': 8,
      'A': 9,
      'A#': 10, 'Bb': 10,
      'B': 11, 'Cb': 11
    };
    
    // Find the lowest note in the voicing to determine octave window
    // The first note in chordNotes array is the bass note for the current inversion
    const bassNote = chordNotes[0];
    const bassSemitone = noteToSemitone[bassNote] ?? 0;
    
    // Create an octave window starting from the bass note
    // We'll show 12 semitones (one octave) starting from the bass note
    const octaveStartSemitone = bassSemitone;
    
    // Generate the notes in our window
    const semitoneToNote = ['C', 'C#', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'Ab', 'A', 'Bb', 'B'];
    const windowNotes: string[] = [];
    for (let i = 0; i < 12; i++) {
      const semitone = (octaveStartSemitone + i) % 12;
      windowNotes.push(semitoneToNote[semitone]);
    }
    
    // Separate into white and black keys based on our window
    const whiteKeyNotes = windowNotes.filter(note => 
      ['C', 'D', 'E', 'F', 'G', 'A', 'B'].includes(note)
    );
    const blackKeyNotes = windowNotes.filter(note => 
      ['C#', 'Eb', 'F#', 'Ab', 'Bb'].includes(note)
    );
    
    // If we don't have 7 white keys, fall back to C-B octave
    const whiteKeys = whiteKeyNotes.length === 7 ? whiteKeyNotes : ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
    const blackKeys = blackKeyNotes.length > 0 ? blackKeyNotes : ['C#', 'D#', 'F#', 'G#', 'A#'];
    
    // Enharmonic equivalents map for matching notes
    const enharmonicMap: Record<string, string[]> = {
      'C': ['C', 'B#'],
      'C#': ['C#', 'Db'],
      'D': ['D'],
      'D#': ['D#', 'Eb'],
      'E': ['E', 'Fb'],
      'F': ['F', 'E#'],
      'F#': ['F#', 'Gb'],
      'G': ['G'],
      'G#': ['G#', 'Ab'],
      'A': ['A'],
      'A#': ['A#', 'Bb'],
      'B': ['B', 'Cb']
    };
    
    // Helper function to check if a note is in the chord (considering enharmonics)
    const isNoteInChord = (key: string): boolean => {
      const equivalents = enharmonicMap[key] || [key];
      return chordNotes.some(note => equivalents.includes(note));
    };
    
    // Helper function to get the position (index) of a note in the current voicing
    // This shows which octave/order the note appears in the inversion
    const getNotePosition = (key: string): number | null => {
      const equivalents = enharmonicMap[key] || [key];
      for (let i = 0; i < chordNotes.length; i++) {
        if (equivalents.includes(chordNotes[i])) {
          return i;
        }
      }
      return null;
    };
    
    // Calculate dimensions based on real piano ratios
    // White key ratio: width 23.5mm : length 150mm = 1:6.38
    // Black key ratio: width 10.5mm : length 90mm = 1:8.57
    const whiteKeyWidth = size.width / 7;
    const whiteKeyHeight = whiteKeyWidth * 6.38; // Proper aspect ratio
    const blackKeyWidth = whiteKeyWidth * 0.447; // 10.5/23.5 = 0.447
    const blackKeyHeight = blackKeyWidth * 8.57; // Proper aspect ratio
    
    // Adjust SVG height to match the white key height
    const pianoHeight = Math.min(whiteKeyHeight, size.height);
    const actualBlackKeyHeight = Math.min(blackKeyHeight, pianoHeight * 0.6);
    
    // Helper to find which white keys a black key sits between
    const getBlackKeyPosition = (blackKey: string): number => {
      // Find the black key in our window
      const blackKeyIndex = windowNotes.indexOf(blackKey);
      if (blackKeyIndex === -1) return -1;
      
      // Count how many white keys come before this black key in the window
      let whiteKeysBefore = 0;
      for (let i = 0; i < blackKeyIndex; i++) {
        if (whiteKeys.includes(windowNotes[i])) {
          whiteKeysBefore++;
        }
      }
      
      // Black key sits between whiteKeysBefore-1 and whiteKeysBefore
      return whiteKeysBefore - 1;
    };

    return (
      <svg width={size.width} height={pianoHeight} className="piano">
        {/* White keys */}
        {whiteKeys.map((key, index: number) => (
          <rect
            key={`white-${key}`}
            x={index * whiteKeyWidth}
            y={0}
            width={whiteKeyWidth - 1}
            height={pianoHeight}
            fill={isNoteInChord(key) ? '#c41e3a' : 'white'}
            stroke="#333"
            strokeWidth={1}
          />
        ))}

        {/* Black keys - dynamically positioned based on window */}
        {blackKeys.map((key) => {
          const whiteKeyIndex = getBlackKeyPosition(key);
          if (whiteKeyIndex < 0) return null;
          
          return (
            <rect
              key={`black-${key}`}
              x={(whiteKeyIndex + 1) * whiteKeyWidth - blackKeyWidth / 2}
              y={0}
              width={blackKeyWidth}
              height={actualBlackKeyHeight}
              fill={isNoteInChord(key) ? '#c41e3a' : '#333'}
              stroke="#000"
              strokeWidth={1}
            />
          );
        })}

        {/* Key labels */}
        {whiteKeys.map((key, index: number) => (
          <text
            key={`label-${key}`}
            x={index * whiteKeyWidth + whiteKeyWidth / 2}
            y={pianoHeight - 5}
            textAnchor="middle"
            fill="#333"
            fontSize={small ? '6' : '8'}
          >
            {key}
          </text>
        ))}
      </svg>
    );
  };

  const renderChordDiagram = () => {
    switch (instrument) {
      case 'ukulele':
      case 'guitar':
      case 'bassGuitar':
      case 'bassUkulele':
      case 'baritoneUkulele':
        return renderFretboardChord(instrument);
      case 'piano':
        return renderPianoChord();
      default:
        return renderFretboardChord('ukulele');
    }
  };

  // Calculate fingering info for display
  const getFingeringInfo = () => {
    const baseChordData = generateChord(chord, instrument);
    if (!baseChordData || typeof baseChordData !== 'object') return { current: 1, total: 1 };
    
    // Handle both array format (legacy piano) and object format
    if (Array.isArray(baseChordData)) {
      // Legacy format - no inversions
      return { current: 1, total: 1 };
    }
    
    const alternatives = baseChordData.inversions || [];
    const totalFingerings = 1 + alternatives.length;
    const currentDisplay = (currentFingeringIndex % totalFingerings) + 1;
    
    return { current: currentDisplay, total: totalFingerings };
  };

  const fingeringInfo = getFingeringInfo();

  return (
    <div 
      className={`chord-chart ${small ? 'small' : ''} ${fingeringInfo.total > 1 ? 'has-alternatives' : ''}`}
      onContextMenu={handleRightClick}
      title={fingeringInfo.total > 1 ? 'Right-click to cycle through fingering alternatives' : ''}
    >
      {renderChordDiagram()}
      <div className="chord-name">
        {chord}
        {/* Show fingering indicator if there are multiple fingerings available */}
        {fingeringInfo.total > 1 && (
          <div className="fingering-info">
            ({fingeringInfo.current}/{fingeringInfo.total})
          </div>
        )}
      </div>
    </div>
  );
};

export default ChordChart;
