// Dynamic chord generation utilities
// This provides fallback chord generation when static data is not available

// Note mapping for semitone calculations (with enharmonic equivalents)
const noteToSemitone: Record<string, number> = {
  'C': 0, 'B#': 0,
  'C#': 1, 'Db': 1,
  'D': 2,
  'D#': 3, 'Eb': 3,
  'E': 4, 'Fb': 4,
  'F': 5, 'E#': 5,
  'F#': 6, 'Gb': 6,
  'G': 7,
  'G#': 8, 'Ab': 8,
  'A': 9,
  'A#': 10, 'Bb': 10,
  'B': 11, 'Cb': 11
};

// Preferred note names for each semitone (for enharmonic normalization)
const semitoneToNote = ['C', 'C#', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'Ab', 'A', 'Bb', 'B'];

// Comprehensive chord intervals (semitones from root)
const chordIntervals: Record<string, number[]> = {
  // Triads
  '': [0, 4, 7],           // Major (default)
  'major': [0, 4, 7],
  'M': [0, 4, 7],
  'm': [0, 3, 7],          // Minor
  'min': [0, 3, 7],
  'minor': [0, 3, 7],
  '-': [0, 3, 7],
  'dim': [0, 3, 6],        // Diminished
  'o': [0, 3, 6],
  '°': [0, 3, 6],
  'aug': [0, 4, 8],        // Augmented
  '+': [0, 4, 8],
  
  // Suspended chords
  'sus': [0, 5, 7],        // Sus4 (default sus)
  'sus2': [0, 2, 7],
  'sus4': [0, 5, 7],
  
  // Seventh chords
  '7': [0, 4, 7, 10],      // Dominant 7th
  'maj7': [0, 4, 7, 11],   // Major 7th
  'M7': [0, 4, 7, 11],
  'Maj7': [0, 4, 7, 11],
  'm7': [0, 3, 7, 10],     // Minor 7th
  'min7': [0, 3, 7, 10],
  '-7': [0, 3, 7, 10],
  'mMaj7': [0, 3, 7, 11],  // Minor major 7th
  'mM7': [0, 3, 7, 11],
  'm(maj7)': [0, 3, 7, 11], // Minor major 7th with parentheses
  'dim7': [0, 3, 6, 9],    // Diminished 7th
  'o7': [0, 3, 6, 9],
  '°7': [0, 3, 6, 9],
  'm7b5': [0, 3, 6, 10],   // Half-diminished 7th
  'ø': [0, 3, 6, 10],
  'ø7': [0, 3, 6, 10],
  '7b5': [0, 4, 6, 10],    // Dominant 7 flat 5
  '7#5': [0, 4, 8, 10],    // Dominant 7 sharp 5 (augmented 7th)
  '7sus4': [0, 5, 7, 10],
  '7sus2': [0, 2, 7, 10],
  
  // Sixth chords
  '6': [0, 4, 7, 9],
  'm6': [0, 3, 7, 9],
  'min6': [0, 3, 7, 9],
  
  // Ninth chords
  '9': [0, 4, 7, 10, 14],
  'maj9': [0, 4, 7, 11, 14],
  'M9': [0, 4, 7, 11, 14],
  'm9': [0, 3, 7, 10, 14],
  'min9': [0, 3, 7, 10, 14],
  'add9': [0, 4, 7, 14],
  'madd9': [0, 3, 7, 14],
  '2': [0, 2, 4, 7],       // Add2 (more common as sus2, but some use as add2)
  
  // Eleventh chords
  '11': [0, 4, 7, 10, 14, 17],
  'm11': [0, 3, 7, 10, 14, 17],
  
  // Thirteenth chords
  '13': [0, 4, 7, 10, 14, 21],
  'maj13': [0, 4, 7, 11, 14, 21],
  'm13': [0, 3, 7, 10, 14, 21],
  
  // Power chord
  '5': [0, 7]
};

// Parse chord symbol to extract root, quality, and bass note
export function parseChord(chordSymbol: string) {
  if (!chordSymbol || typeof chordSymbol !== 'string') return null;
  
  // Normalize input: trim and handle Unicode symbols
  const normalized = chordSymbol.trim()
    .replace(/♯/g, '#')
    .replace(/♭/g, 'b')
    .replace(/°7/g, 'dim7')     // Handle dim7 symbol before general dim
    .replace(/°/g, 'dim')
    .replace(/ø7/g, 'm7b5')     // Half-diminished with 7
    .replace(/ø/g, 'm7b5')      // Half-diminished
    .replace(/△7/g, 'maj7')     // Major 7 triangle with 7
    .replace(/△/g, 'maj7')      // Major 7 triangle alone
    .replace(/Δ7/g, 'maj7')     // Major 7 delta with 7
    .replace(/Δ/g, 'maj7');     // Major 7 delta alone
  
  // Handle slash chords (inversions)
  const slashParts = normalized.split('/');
  const mainChord = slashParts[0];
  const bassNote = slashParts[1] || null;
  
  // Extract root note (including accidentals)
  // Match: A-G followed by optional # or b (or double sharps/flats)
  const rootMatch = mainChord.match(/^([A-G][#b]*)/i);
  if (!rootMatch) return null;
  
  const root = rootMatch[1];
  let quality = mainChord.slice(root.length);
  
  // Handle common alternate spellings
  quality = quality
    .replace(/^min(?!or)/, 'm')    // "min7" -> "m7" but keep "minor"
    .replace(/^minor/, 'm')         // "minor" -> "m"
    .replace(/^Maj/, 'maj')         // Normalize case
    .replace(/^Major/, 'major')
    .replace(/^MIN/, 'm')
    .replace(/^MAJOR/, 'major');
  
  // If empty, it's a major chord
  if (!quality) {
    quality = '';  // Use empty string for major (matches our lookup table)
  }
  
  return { root, quality, bassNote };
}

// Normalize note name for enharmonic equivalence
function normalizeNote(note: string): string {
  const semitone = noteToSemitone[note];
  if (semitone === undefined) return note;
  return semitoneToNote[semitone];
}

// Generate chord notes from chord symbol
export function getChordNotes(chordSymbol: string): string[] | null {
  const parsed = parseChord(chordSymbol);
  if (!parsed) return null;
  
  const { root, quality, bassNote } = parsed;
  
  // Look up root semitone
  const rootSemitone = noteToSemitone[root];
  if (rootSemitone === undefined) return null;
  
  // Look up intervals for this chord quality
  const intervals = chordIntervals[quality];
  if (!intervals) {
    // If quality not found, try treating it as major
    console.warn(`Unknown chord quality "${quality}" in "${chordSymbol}", defaulting to major`);
    return getChordNotes(root); // Fallback to root major
  }
  
  // Generate chord tones by adding intervals to root
  const chordNotes = intervals.map((interval: number) => {
    const semitone = (rootSemitone + interval) % 12;
    return semitoneToNote[semitone];
  });
  
  // Handle slash chords (bass note inversions)
  if (bassNote) {
    const normalizedBass = normalizeNote(bassNote);
    const bassSemitone = noteToSemitone[bassNote];
    
    if (bassSemitone === undefined) {
      console.warn(`Invalid bass note "${bassNote}" in slash chord "${chordSymbol}"`);
      return chordNotes;
    }
    
    // Remove bass note from chord if it's already there (to avoid duplication)
    const filteredNotes = chordNotes.filter((note: string) => {
      const noteSemitone = noteToSemitone[note];
      return noteSemitone !== bassSemitone;
    });
    
    // Put bass note first
    return [normalizedBass, ...filteredNotes];
  }
  
  return chordNotes;
}

// Helper: Find all possible voicings for a chord on guitar
function findGuitarVoicings(targetSemitones: number[], tuningSemitones: number[], maxFret: number = 12) {
  const voicings: number[][] = [];
  
  // Try different starting positions
  for (let basePosition = 0; basePosition <= maxFret - 4; basePosition++) {
    const frets = new Array(6).fill(-1);
    let validVoicing = true;
    let usedNotes = new Set<number>();
    
    // For each string, find a chord tone within a 4-fret span from the base position
    for (let string = 0; string < 6; string++) {
      let found = false;
      
      // Try open string first if we're in first position
      if (basePosition <= 1) {
        const openNoteSemitone = tuningSemitones[string] % 12;
        if (targetSemitones.includes(openNoteSemitone)) {
          frets[string] = 0;
          usedNotes.add(openNoteSemitone);
          found = true;
        }
      }
      
      // Try frets within the position (4-fret span)
      if (!found) {
        for (let fret = basePosition; fret <= Math.min(basePosition + 4, maxFret); fret++) {
          if (fret === 0) continue; // Already tried open
          const noteSemitone = (tuningSemitones[string] + fret) % 12;
          if (targetSemitones.includes(noteSemitone)) {
            frets[string] = fret;
            usedNotes.add(noteSemitone);
            found = true;
            break;
          }
        }
      }
      
      // If we can't find a note for this string, we might mute it (except bass strings for root)
      if (!found && string >= 2) {
        frets[string] = -1; // Mute
      } else if (!found) {
        validVoicing = false;
        break;
      }
    }
    
    // Check if this voicing includes all essential chord tones (at least root, 3rd/4th, and 5th)
    if (validVoicing && usedNotes.size >= Math.min(3, targetSemitones.length)) {
      voicings.push([...frets]);
    }
  }
  
  return voicings;
}

// Helper: Score a guitar voicing (lower is better)
function scoreGuitarVoicing(frets: number[], targetSemitones: number[], tuningSemitones: number[], preferredBass?: number): number {
  let score = 0;
  
  // Calculate fret span (prefer compact voicings)
  const activeFrets = frets.filter(f => f > 0);
  if (activeFrets.length > 0) {
    const span = Math.max(...activeFrets) - Math.min(...activeFrets);
    score += span * 10; // Penalize wide spans
  }
  
  // Prefer lower positions (easier to play)
  const avgFret = activeFrets.length > 0 
    ? activeFrets.reduce((sum, f) => sum + f, 0) / activeFrets.length 
    : 0;
  score += avgFret * 2;
  
  // Count muted strings (prefer fewer muted strings, but not critical)
  const mutedStrings = frets.filter(f => f === -1).length;
  score += mutedStrings * 5;
  
  // Prefer voicings that include the bass note on the lowest string
  if (preferredBass !== undefined) {
    const lowestPlayedString = frets.findIndex(f => f >= 0);
    if (lowestPlayedString >= 0) {
      const bassSemitone = (tuningSemitones[lowestPlayedString] + frets[lowestPlayedString]) % 12;
      if (bassSemitone !== preferredBass) {
        score += 20; // Penalty for wrong bass note
      }
    }
  }
  
  // Prefer more open strings (easier)
  const openStrings = frets.filter(f => f === 0).length;
  score -= openStrings * 3;
  
  return score;
}

// Generate a basic chord fingering for guitar (6 strings)
export function generateGuitarChord(chordSymbol: string) {
  const notes = getChordNotes(chordSymbol);
  if (!notes) return null;
  
  // Standard guitar tuning: E2, A2, D3, G3, B3, E4 (low to high)
  const tuning = ['E', 'A', 'D', 'G', 'B', 'E'];
  const tuningSemitones = tuning.map((note: string) => noteToSemitone[note]);
  const targetSemitones = notes.map((note: string) => noteToSemitone[note]);
  
  // For slash chords, the first note is the preferred bass
  const preferredBass = notes.length > 0 ? noteToSemitone[notes[0]] : undefined;
  
  // Find all possible voicings
  const allVoicings = findGuitarVoicings(targetSemitones, tuningSemitones, 15);
  
  if (allVoicings.length === 0) {
    // Fallback: very simple first-position attempt
    const frets = new Array(6).fill(-1);
    for (let string = 0; string < 6; string++) {
      for (let fret = 0; fret <= 4; fret++) {
        const noteSemitone = (tuningSemitones[string] + fret) % 12;
        if (targetSemitones.includes(noteSemitone)) {
          frets[string] = fret;
          break;
        }
      }
    }
    
    return {
      frets,
      fingers: generateFingers(frets),
      description: `Generated ${chordSymbol} (simplified)`,
      generated: true,
      inversions: []
    };
  }
  
  // Score all voicings
  const scoredVoicings = allVoicings.map(voicing => ({
    voicing,
    score: scoreGuitarVoicing(voicing, targetSemitones, tuningSemitones, preferredBass)
  }));
  
  // Sort by score (best first)
  scoredVoicings.sort((a, b) => a.score - b.score);
  
  // Take the best voicing as primary
  const bestVoicing = scoredVoicings[0].voicing;
  
  // Create inversions array with alternative voicings
  // Group by position and take best from each position range
  const positionGroups = new Map<string, typeof scoredVoicings[0]>();
  
  for (const scored of scoredVoicings) {
    const activeFrets = scored.voicing.filter(f => f > 0);
    if (activeFrets.length === 0) continue;
    
    const minFret = Math.min(...activeFrets);
    const positionKey = Math.floor(minFret / 3) * 3; // Group by position (0-2, 3-5, 6-8, etc.)
    
    if (!positionGroups.has(positionKey.toString()) || 
        scored.score < positionGroups.get(positionKey.toString())!.score) {
      positionGroups.set(positionKey.toString(), scored);
    }
  }
  
  // Convert to inversions array, excluding the best voicing
  const inversions = Array.from(positionGroups.values())
    .filter(scored => scored.voicing !== bestVoicing)
    .slice(0, 4) // Limit to 4 alternative voicings
    .map(scored => ({
      frets: scored.voicing,
      fingers: generateFingers(scored.voicing),
      description: `Position ${Math.min(...scored.voicing.filter(f => f > 0)) || 0}+`
    }));
  
  return {
    frets: bestVoicing,
    fingers: generateFingers(bestVoicing),
    description: `Generated ${chordSymbol}`,
    generated: true,
    inversions
  };
}

// Generate finger assignments for a fret pattern
function generateFingers(frets: number[]): number[] {
  const fingers = new Array(frets.length).fill(0);
  const activeFrets = frets.map((f, i) => ({ fret: f, string: i })).filter(({ fret }) => fret > 0);
  
  if (activeFrets.length === 0) return fingers;
  
  // Sort by fret position
  activeFrets.sort((a, b) => a.fret - b.fret);
  
  // Check for barre chord (multiple strings on same fret)
  const fretCounts = new Map<number, number>();
  activeFrets.forEach(({ fret }) => {
    fretCounts.set(fret, (fretCounts.get(fret) || 0) + 1);
  });
  
  // Find if there's a barre (3+ strings on same fret at lowest position)
  const lowestFret = activeFrets[0].fret;
  const lowestFretCount = fretCounts.get(lowestFret) || 0;
  const isBarre = lowestFretCount >= 3;
  
  if (isBarre) {
    // Assign finger 1 to all strings at the barre fret
    frets.forEach((fret, i) => {
      if (fret === lowestFret) fingers[i] = 1;
    });
    
    // Assign fingers 2, 3, 4 to higher frets
    let fingerNum = 2;
    activeFrets.forEach(({ fret, string }) => {
      if (fret > lowestFret && fingerNum <= 4) {
        fingers[string] = fingerNum;
        fingerNum++;
      }
    });
  } else {
    // Simple assignment: fingers 1-4 for frets in order
    let fingerNum = 1;
    activeFrets.forEach(({ fret, string }) => {
      if (fingerNum <= 4) {
        fingers[string] = fingerNum;
        fingerNum++;
      }
    });
  }
  
  return fingers;
}

// Helper: Find all possible voicings for ukulele
function findUkuleleVoicings(targetSemitones: number[], tuningSemitones: number[], maxFret: number = 7) {
  const voicings: number[][] = [];
  
  // Try different starting positions (ukulele typically uses first 7 frets)
  for (let basePosition = 0; basePosition <= maxFret - 3; basePosition++) {
    const frets = new Array(4).fill(-1);
    let validVoicing = true;
    let usedNotes = new Set<number>();
    
    // For each string, find a chord tone within a 3-fret span
    for (let string = 0; string < 4; string++) {
      let found = false;
      
      // Try open string first if in first position
      if (basePosition <= 1) {
        const openNoteSemitone = tuningSemitones[string] % 12;
        if (targetSemitones.includes(openNoteSemitone)) {
          frets[string] = 0;
          usedNotes.add(openNoteSemitone);
          found = true;
        }
      }
      
      // Try frets within position
      if (!found) {
        for (let fret = basePosition; fret <= Math.min(basePosition + 3, maxFret); fret++) {
          if (fret === 0) continue;
          const noteSemitone = (tuningSemitones[string] + fret) % 12;
          if (targetSemitones.includes(noteSemitone)) {
            frets[string] = fret;
            usedNotes.add(noteSemitone);
            found = true;
            break;
          }
        }
      }
      
      if (!found) {
        validVoicing = false;
        break;
      }
    }
    
    // Ukulele voicings should use all 4 strings (no muted strings typically)
    if (validVoicing && usedNotes.size >= Math.min(3, targetSemitones.length)) {
      voicings.push([...frets]);
    }
  }
  
  return voicings;
}

// Helper: Score a ukulele voicing
function scoreUkuleleVoicing(frets: number[]): number {
  let score = 0;
  
  // Calculate fret span (prefer compact)
  const activeFrets = frets.filter(f => f > 0);
  if (activeFrets.length > 0) {
    const span = Math.max(...activeFrets) - Math.min(...activeFrets);
    score += span * 8;
  }
  
  // Prefer lower positions
  const avgFret = activeFrets.length > 0
    ? activeFrets.reduce((sum, f) => sum + f, 0) / activeFrets.length
    : 0;
  score += avgFret * 2;
  
  // Prefer open strings
  const openStrings = frets.filter(f => f === 0).length;
  score -= openStrings * 5;
  
  return score;
}

// Generate a basic chord fingering for ukulele (4 strings)
export function generateUkuleleChord(chordSymbol: string) {
  const notes = getChordNotes(chordSymbol);
  if (!notes) return null;
  
  // Standard ukulele tuning: G4, C4, E4, A4 (re-entrant tuning, high G)
  const tuning = ['G', 'C', 'E', 'A'];
  const tuningSemitones = tuning.map((note: string) => noteToSemitone[note]);
  const targetSemitones = notes.map((note: string) => noteToSemitone[note]);
  
  // Find all possible voicings (increased range for more options)
  const allVoicings = findUkuleleVoicings(targetSemitones, tuningSemitones, 10);
  
  if (allVoicings.length === 0) {
    // Fallback: simple first-position attempt
    const frets = new Array(4).fill(0);
    for (let string = 0; string < 4; string++) {
      for (let fret = 0; fret <= 4; fret++) {
        const noteSemitone = (tuningSemitones[string] + fret) % 12;
        if (targetSemitones.includes(noteSemitone)) {
          frets[string] = fret;
          break;
        }
      }
    }
    
    return {
      frets,
      fingers: generateFingers(frets),
      description: `Generated ${chordSymbol} (simplified)`,
      generated: true,
      inversions: []
    };
  }
  
  // Score all voicings
  const scoredVoicings = allVoicings.map(voicing => ({
    voicing,
    score: scoreUkuleleVoicing(voicing)
  }));
  
  // Sort by score (best first)
  scoredVoicings.sort((a, b) => a.score - b.score);
  
  // Take the best voicing as primary
  const bestVoicing = scoredVoicings[0].voicing;
  
  // Create inversions array with alternative voicings
  // Group by position to provide variety
  const positionGroups = new Map<string, typeof scoredVoicings[0]>();
  
  for (const scored of scoredVoicings) {
    const activeFrets = scored.voicing.filter(f => f > 0);
    if (activeFrets.length === 0) continue;
    
    const minFret = Math.min(...activeFrets);
    const positionKey = Math.floor(minFret / 2) * 2; // Group by position (0-1, 2-3, 4-5, etc.)
    
    if (!positionGroups.has(positionKey.toString()) || 
        scored.score < positionGroups.get(positionKey.toString())!.score) {
      positionGroups.set(positionKey.toString(), scored);
    }
  }
  
  // Convert to inversions array, excluding the best voicing
  const inversions = Array.from(positionGroups.values())
    .filter(scored => scored.voicing !== bestVoicing)
    .slice(0, 3) // Limit to 3 alternative voicings for ukulele
    .map(scored => ({
      frets: scored.voicing,
      fingers: generateFingers(scored.voicing),
      description: `Position ${Math.min(...scored.voicing.filter(f => f > 0)) || 0}+`
    }));
  
  return {
    frets: bestVoicing,
    fingers: generateFingers(bestVoicing),
    description: `Generated ${chordSymbol}`,
    generated: true,
    inversions
  };
}

// Generate basic chord fingering for bass guitar (4 strings)
export function generateBassGuitarChord(chordSymbol: string) {
  const notes = getChordNotes(chordSymbol);
  if (!notes) return null;
  
  // Standard bass tuning: E1, A1, D2, G2 (low to high)
  const tuning = ['E', 'A', 'D', 'G'];
  const tuningSemitones = tuning.map((note: string) => noteToSemitone[note]);
  const targetSemitones = notes.map((note: string) => noteToSemitone[note]);
  
  const bassSemitone = targetSemitones[0]; // First note is the bass
  
  // Generate multiple voicings at different positions
  const voicings: number[][] = [];
  
  // Try different starting frets for the bass note
  for (let baseFret = 0; baseFret <= 12; baseFret++) {
    for (let bassString = 0; bassString < 2; bassString++) {
      const noteSemitone = (tuningSemitones[bassString] + baseFret) % 12;
      if (noteSemitone !== bassSemitone) continue;
      
      const frets = new Array(4).fill(-1);
      frets[bassString] = baseFret;
      
      // Fill in other chord tones on higher strings
      for (let string = bassString + 1; string < 4; string++) {
        for (let fret = baseFret; fret <= Math.min(baseFret + 4, 15); fret++) {
          const stringNote = (tuningSemitones[string] + fret) % 12;
          if (targetSemitones.includes(stringNote)) {
            frets[string] = fret;
            break;
          }
        }
      }
      
      // Check if we got enough notes
      const playedStrings = frets.filter(f => f !== -1).length;
      if (playedStrings >= 2) {
        voicings.push([...frets]);
      }
    }
  }
  
  if (voicings.length === 0) {
    // Fallback
    const frets = new Array(4).fill(-1);
    frets[0] = 0;
    return {
      frets,
      fingers: generateFingers(frets),
      description: `Generated ${chordSymbol}`,
      generated: true,
      inversions: []
    };
  }
  
  // Sort by bass position (lower positions first)
  voicings.sort((a, b) => {
    const aMin = Math.min(...a.filter(f => f >= 0));
    const bMin = Math.min(...b.filter(f => f >= 0));
    return aMin - bMin;
  });
  
  // Take first as primary
  const bestVoicing = voicings[0];
  
  // Create inversions - take one from each position range
  const positionGroups = new Map<number, number[]>();
  for (const voicing of voicings) {
    const minFret = Math.min(...voicing.filter(f => f >= 0));
    const positionKey = Math.floor(minFret / 3) * 3;
    
    if (!positionGroups.has(positionKey)) {
      positionGroups.set(positionKey, voicing);
    }
  }
  
  const inversions = Array.from(positionGroups.values())
    .filter(v => v !== bestVoicing)
    .slice(0, 3)
    .map(voicing => ({
      frets: voicing,
      fingers: generateFingers(voicing),
      description: `Position ${Math.min(...voicing.filter(f => f >= 0))}`
    }));
  
  return {
    frets: bestVoicing,
    fingers: generateFingers(bestVoicing),
    description: `Generated ${chordSymbol}`,
    generated: true,
    inversions
  };
}

// Generate piano chord (note list with proper voicing)
export function generatePianoChord(chordSymbol: string) {
  const notes = getChordNotes(chordSymbol);
  if (!notes) return null;
  
  // For piano, return notes in a comfortable voicing with inversions
  const parsed = parseChord(chordSymbol);
  if (!parsed) return notes; // Fallback to simple array for backward compatibility
  
  const { root, bassNote } = parsed;
  
  // Limit to 4-5 notes for readability
  const maxNotes = 5;
  let baseNotes = notes.length <= maxNotes ? notes : notes.slice(0, maxNotes);
  
  // Don't generate inversions for slash chords (they already specify the bass)
  if (bassNote) {
    return baseNotes;
  }
  
  // Generate inversions for triads and 7th chords (3-4 notes)
  const inversions = [];
  if (baseNotes.length >= 3 && baseNotes.length <= 4) {
    // 1st inversion: move root note up (visually moves the octave window)
    const firstInversion = [...baseNotes.slice(1), baseNotes[0]];
    inversions.push(firstInversion);
    
    // 2nd inversion: move first two notes up
    const secondInversion = [...baseNotes.slice(2), baseNotes[0], baseNotes[1]];
    inversions.push(secondInversion);
    
    // For 7th chords, add 3rd inversion
    if (baseNotes.length === 4) {
      const thirdInversion = [...baseNotes.slice(3), baseNotes[0], baseNotes[1], baseNotes[2]];
      inversions.push(thirdInversion);
    }
  }
  
  // Return object with inversions (like guitar/ukulele chords)
  return {
    notes: baseNotes,
    inversions: inversions.length > 0 ? inversions : undefined,
    isGenerated: true
  };
}

// Main generator function that dispatches to instrument-specific generators
export function generateChord(chordSymbol: string, instrument: string) {
  switch (instrument) {
    case 'guitar':
      return generateGuitarChord(chordSymbol);
    case 'ukulele':
    case 'baritoneUkulele':
      return generateUkuleleChord(chordSymbol);
    case 'bassGuitar':
    case 'bassUkulele':
      return generateBassGuitarChord(chordSymbol);
    case 'piano':
      return generatePianoChord(chordSymbol);
    default:
      return null;
  }
}
